def create_db():
    conn = sqlite3.connect('machineQuestioning.db')
    cursor = conn.cursor()

    cursor.execute('DROP TABLE IF EXISTS questions')
    cursor.execute('''
        CREATE TABLE questions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chapter TEXT NOT NULL,
            question TEXT NOT NULL,
            option_1 TEXT NOT NULL,
            option_2 TEXT NOT NULL,
            option_3 TEXT NOT NULL,
            option_4 TEXT NOT NULL,
            correct_index INTEGER NOT NULL,
            explanation TEXT NOT NULL
        )
    ''')

    for q in QUESTIONS:
        cursor.execute('''
            INSERT INTO questions (chapter, question, option_1, option_2, option_3, option_4, correct_index, explanation)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ''', (
            q['chapter'], 
            q['question'], 
            q['options'][0], 
            q['options'][1], 
            q['options'][2], 
            q['options'][3], 
            q['correct_index'], 
            q['explanation']
        ))

    conn.commit()
    conn.close()
    print("Η βάση δεδομένων 'machineQuestioning.db' δημιουργήθηκε επιτυχώς με 82 ερωτήσεις!")

if __name__ == '__main__':
    create_db()